import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Day CERN 2019: Ceph in Compute Canada - Mike Cave","description":"","frontmatter":{"title":"Ceph Day CERN 2019: Ceph in Compute Canada - Mike Cave","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","Distributed Storage","Compute Canada","High Availability","Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_in_Compute_Canada_-_Mike_Cave.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_in_Compute_Canada_-_Mike_Cave.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Day_CERN_2019_-_Ceph_in_Compute_Canada_-_Mike_Cave.md"};function n(p,e,C,_,s,l){return a(),i("div",null,[...e[0]||(e[0]=[o("<p>会议纪要</p><p>会议主题：Compute Canada 中 Ceph 的使用情况介绍</p><p>主讲人：Mike Cave</p><ul><li><strong>职位</strong>：Senior Unix Administrator</li><li><strong>单位</strong>：University of Victoria, Research Computing Support</li></ul><p>Compute Canada 概述</p><ul><li><strong>性质</strong>：加拿大国家数字计算研究平台，提供研究人员HPC资源、云资源、存储、备份等服务。</li><li><strong>资金模型</strong>：联合资助模式，由四个联盟共同运作：West Grid, Compute Ontario, Calcul Quebec, ACENET。</li><li><strong>服务站点</strong>：全国五个主要站点，支持超过70个机构。</li><li><strong>网络</strong>：100 Gigabit 全国网络。</li></ul><p>Ceph 在 Compute Canada 的应用</p><ul><li><strong>Ceph部署</strong>：所有云站点均使用Ceph，存储规模从4.5 PB到100 TB不等。</li><li><strong>Arbutus云</strong>：Compute Canada最大云部署，提供10,000物理核心，虚拟化后提供近20,000核心，4.5 PB可用存储。</li><li><strong>Ceph部署历史</strong>：从初始的500 TB三重复制存储，手动部署，到现在的32个OSD节点，640个OSD，5.3 PB原始存储，使用BlueStore和Erasure Coded Profile。</li></ul><p>监控与管理</p><ul><li><strong>监控系统</strong>：使用UV Stats、Prometheus、Grafana进行系统监控。</li><li><strong>日志管理</strong>：通过Flare系统集中管理日志，实现基于事件的智能报警。</li></ul><p>后续行动计划</p><ul><li><strong>数据迁移</strong>：用户自行迁移数据到新集群。</li><li><strong>硬件更新</strong>：逐步淘汰旧硬件，引入新硬件。</li><li><strong>持续监控</strong>：继续优化监控系统，确保集群稳定运行。</li></ul><p>结论 Mike Cave 介绍了Compute Canada在Ceph存储解决方案的应用和发展历程，强调了联合资助模式在资源共享和硬件更新方面的重要性，并展示了如何通过先进的监控和管理工具确保系统的高可用性和性能。此外，他还详细介绍了Ceph部署的演进过程，包括从手动部署到自动化部署，以及使用BlueStore和Erasure Coded Profile等新技术。</p>",13)])])}const g=t(r,[["render",n]]);export{d as __pageData,g as default};
